if (!base) throw new Error('LENDLOOP_CONVEX_SITE_URL is not set');
const body = JSON.stringify({ ticket: ctx.ticket });
const headers = llSign({ keys: $env.LENDLOOP_N2C_KEYS, method: 'POST', route: '/n8n/notifications/redeem', body });
