const prev = $('Sign: redeem ticket').first().json;
// Report only the error itself (never the signed request/headers).
const j = $input.first().json;
const e = j.error || {};
const detail = (typeof e === 'string' ? e : [e.httpCode || e.status || '', e.message || '', e.description || ''].join(' ').trim() || 'unknown error').slice(0, 300);
if (/\b410\b/.test(detail)) {
  console.log('[lendloop] redeem ticket: ticket no longer valid (already handled or superseded); stopping quietly');
  return [];
}
if (/\b(400|401|403|413|422)\b/.test(detail)) {
  throw new Error('redeem ticket rejected by Convex (not retryable): ' + detail);
}
const attempt = (prev.attempt || 0) + 1;
if (attempt >= 4) {
  throw new Error('redeem ticket failed after ' + attempt + ' attempts: ' + detail);
}
return [{ json: { ctx: prev.ctx, attempt } }];

